import{_ as d,o as a,c as r,a0 as e}from"./chunks/framework.CShDTZbC.js";const b=JSON.parse('{"title":"附录 A · 量化术语速查表（人话版）","description":"","frontmatter":{},"headers":[],"relativePath":"book/appendix/a-terms.md","filePath":"book/appendix/a-terms.md","lastUpdated":1788537144000}'),o={name:"book/appendix/a-terms.md"};function h(l,t,i,s,n,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="附录-a-·-量化术语速查表-人话版" tabindex="-1">附录 A · 量化术语速查表（人话版） <a class="header-anchor" href="#附录-a-·-量化术语速查表-人话版" aria-label="Permalink to &quot;附录 A · 量化术语速查表（人话版）&quot;">​</a></h1><blockquote><p>按拼音/字母排序，持续补充。看不懂的术语，随时用第 21 章的 AI 私教提问法深挖。</p></blockquote><h2 id="a-c" tabindex="-1">A-C <a class="header-anchor" href="#a-c" aria-label="Permalink to &quot;A-C&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>人话解释</th></tr></thead><tbody><tr><td>Alpha（α）</td><td>超过大盘的那部分收益——真本事的部分</td></tr><tr><td>Backtest 回测</td><td>把策略放到历史数据上&quot;假装交易&quot;一遍，看成绩</td></tr><tr><td>Beta（β）</td><td>跟着大盘一起涨跌的部分——随大流的部分</td></tr><tr><td>最大回撤 Max Drawdown</td><td>净值从最高点跌下来最惨的那一刀深度</td></tr><tr><td>夏普比率 Sharpe</td><td>每承担一份波动，换来多少收益。&gt;1 及格，&gt;2 优秀</td></tr><tr><td>幸存者偏差</td><td>只统计&quot;活下来&quot;的样本导致的乐观错觉</td></tr></tbody></table><h2 id="f-p" tabindex="-1">F-P <a class="header-anchor" href="#f-p" aria-label="Permalink to &quot;F-P&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>人话解释</th></tr></thead><tbody><tr><td>因子 Factor</td><td>一个&quot;打分维度&quot;：估值、动量、波动率……</td></tr><tr><td>未来函数 Look-ahead Bias</td><td>算信号时偷看了&quot;当时不可能知道的数据&quot;——回测造假第一原理</td></tr><tr><td>过拟合 Overfitting</td><td>把历史噪声背下来了，不是规律——历史满分，实盘垫底</td></tr><tr><td>前复权 / 后复权</td><td>把分红除权造成的价格跳空修正掉，否则收益率全是假的</td></tr><tr><td>滑点 Slippage</td><td>你想 10 块买，实际成交 10.01——市场的&quot;办事费&quot;</td></tr><tr><td>换手率 Turnover</td><td>策略倒手的频率，越高摩擦成本越吃收益</td></tr></tbody></table><h2 id="q-z" tabindex="-1">Q-Z <a class="header-anchor" href="#q-z" aria-label="Permalink to &quot;Q-Z&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>人话解释</th></tr></thead><tbody><tr><td>样本外验证 Out-of-sample</td><td>用&quot;没参与调参&quot;的历史数据再考一次——防过拟合的疫苗</td></tr><tr><td>胜率 Win Rate</td><td>赚钱交易占全部交易的比例（高胜率 ≠ 赚钱，见盈亏比）</td></tr><tr><td>盈亏比</td><td>平均每笔赚的钱 ÷ 平均每笔亏的钱</td></tr><tr><td>IC / IR</td><td>因子预测能力的体检指标（第 15 章展开）</td></tr><tr><td>拥挤交易 Crowded Trade</td><td>大家都挤同一策略，alpha 被挤没了</td></tr><tr><td>处置效应</td><td>赚的拿不住、亏的扛到底——人类的通病</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 用法</p><p>术语看不懂 → 先查本表 → 还不懂 → 用 <a href="/book/part4/ch21.html">第 21 章</a> 的 AI 私教模板追问 → 懂了之后回来建议猫哥补充本表。</p></div>',9)])])}const u=d(o,[["render",h]]);export{b as __pageData,u as default};
